mapper.select:
SELECT c.id, c.class_name, c.teacher_id, c.description, c.create_time, u.real_name AS teacher_name, (SELECT COUNT(*) FROM student WHERE class_id = c.id AND is_deleted = 0) AS student_count FROM class c LEFT JOIN sys_user u ON c.teacher_id = u.id AND u.is_deleted = 0 WHERE c.is_deleted = 0
AND c.class_name LIKE CONCAT('%', #{className}, '%')
ORDER BY c.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM class
WHERE class_name = #{className} AND is_deleted = 0

    AND id != #{excludeId}
